        TEW_R(IN := EW_R, PT := T#1s);
        IF TNS_G.Q AND TEW_R.Q THEN State := 1 END_IF;
    1 :
        NS_G := FALSE; NS_Y := TRUE; NS_R := FALSE;
        EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
        TNS_Y(IN := NS_Y, PT := T#1s);
        TEW_R(IN := EW_R, PT := T#1s);
        IF TNS_Y.Q AND TEW_R.Q THEN State := 2 END_IF;
    2 :
        NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
        EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
        TNS_R(IN := NS_R, PT := T#1s);
        TEW_R(IN := EW_R, PT := T#1s);
        IF TNS_R.Q AND TEW_R.Q THEN State := 3 END_IF;
    3 :
        NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
        EW_G := TRUE; EW_Y := FALSE; EW_R := FALSE;
        TEW_G(IN := EW_G, PT := T#2s);
        NS_R(IN := NS_R, PT := T#1s);
        IF TEW_G.Q AND NS_R.Q THEN State := 4 END_IF;
    4 :
        NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
        EW_G := FALSE; EW_Y := TRUE; EW_R := FALSE;
        TEW_Y(IN := EW_Y, PT := T#1s);
        NS_R(IN := NS_R, PT := T#1s);
        IF TEW_Y.Q AND NS_R.Q THEN State := 5 END_IF;
    5 :
        NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
        EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
        TEW_R(IN := EW_R, PT := T#1s);
        NS_R(IN := NS_R, PT := T#1s);
        IF TEW_R.Q AND NS_R.Q THEN State := 0 END_IF;
END_CASE;

END_PROGRAM

