        MotorUp := FALSE;
        MotorDown := CallDown AND DoorClosed AND NOT AtBottom;
        IF CallUp AND DoorClosed AND NOT AtBottom THEN
            State := 1;
        ELSIF NOT CallDown THEN
            State := 0;
        END_IF;

    3: // Moving-down
        MotorUp := FALSE;
        MotorDown := TRUE;
        IF AtBottom OR NOT CallDown THEN
            State := 0;
        END_IF;

    ELSE
        State := 0;
END_CASE;

