PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR
VAR CONSTANT
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    LIQ_MIN : INT := 10;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
END_VAR
VAR
    State : INT := 0;
END_VAR
IF NOT EStop THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
ELSIF StartBatch AND EStop THEN
    CASE State OF
        0 :
            IF Level >= LIQ_MIN THEN
                State := 1;
            END_IF;
        1 :
            IF Level >= LVL_HIGH THEN
                State := 2;
            ELSE
                FillValve := TRUE;
                Heater := FALSE;
                Agitator := FALSE;
                DrainValve := FALSE;
            END_IF;
        2 :
            IF Temp >= TEMP_SET THEN
                State := 3;
            ELSE
                FillValve := FALSE;
                Heater := TRUE;
                Agitator := TRUE;
                DrainValve := FALSE;
            END_IF;
        3 :
            IF Temp >= TEMP_SET AND NOT PT_REACT.TON() THEN
                State := 4;
                PT_REACT(IN := TRUE, PT := PT_REACT);
            END_IF;
        4 :
            IF Level <= LVL_LOW THEN
                State := 0;
            ELSE
                FillValve := FALSE;
                Heater := FALSE;
                Agitator := FALSE;
                DrainValve := TRUE;
            END_IF;
    END_CASE;
END_IF;

END_PROGRAM

