            Agitator := TRUE;
            DrainValve := FALSE;
            IF Temp >= TEMP_SET THEN
                State := 3;
            END_IF;

        3:  // React
            FillValve := FALSE;
            Heater := TRUE;
            Agitator := TRUE;
            DrainValve := FALSE;
            T1(IN := TRUE, PT := PT_REACT);
            IF NOT T1.Q THEN
                State := 4;
            END_IF;

        4:  // Drain
            FillValve := FALSE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := TRUE;
            IF Level <= LVL_LOW THEN
                State := 0;
            END_IF;
    END_CASE;
