    LVL_LOW : INT := 5;
    LIQ_MIN : INT := 10;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
END_VAR
VAR
    State : INT := 0;
    T1 : TON;
END_VAR

IF NOT EStop THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
ELSIF StartBatch AND Level >= LIQ_MIN THEN
    CASE State OF
        0:
            IF Level >= LVL_HIGH THEN
                State := 1;
            END_IF;
        1:
            FillValve := TRUE;
            IF Level >= LVL_HIGH THEN
                State := 2;
                T1(IN := TRUE, PT := T#1s);
            END_IF;
        2:
            Heater := TRUE;
            Agitator := TRUE;
            IF Temp >= TEMP_SET AND T1.Q THEN
                State := 3;
                T1(IN := TRUE, PT := PT_REACT);
            END_IF;
        3:
            Heater := TRUE;
            Agitator := TRUE;
            IF T1.Q THEN
                State := 4;
                T1(IN := TRUE, PT := T#1s);
            END_IF;
        4:
            DrainValve := TRUE;
            IF Level <= LVL_LOW THEN
                State := 0;
            END_IF;
    END_CASE;
ELSE
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
END_IF;

END_PROGRAM

