    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
ELSIF StartBatch AND State = 0 AND Level >= LIQ_MIN THEN
    State := 1;
ELSIF State = 1 AND Level >= LVL_HIGH THEN
    State := 2;
ELSIF State = 2 AND Temp >= TEMP_SET THEN
    State := 3;
ELSIF State = 3 AND TON(Ticks := PT_REACT).Q THEN
    State := 4;
ELSIF State = 4 AND Level <= LVL_LOW THEN
    State := 0;
END_IF;

CASE State OF
    0:
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
    1:
        FillValve := TRUE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
    2:
