        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;
    3:
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;
    4:
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := TRUE;
END_CASE;

IF FillValve AND DrainValve OR Level < LIQ_MIN THEN
    Heater := FALSE;
    Agitator := FALSE;
END_IF;

