    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
END_VAR

IF NOT EStop THEN
    State := 0;
END_IF;

CASE State OF
    0: -- Idle
        IF StartBatch AND Level >= LIQ_MIN THEN
            State := 1;
        END_IF;

    1: -- Fill
        FillValve := TRUE;
        IF Level >= LVL_HIGH THEN
            State := 2;
        END_IF;

    2: -- Heat
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        IF Temp >= TEMP_SET THEN
            State := 3;
        END_IF;

    3: -- React
        Heater := TRUE;
        Agitator := TRUE;
        IF Ticks >= PT_REACT THEN
            State := 4;
        END_IF;

    4: -- Drain
        FillValve := FALSE;
        DrainValve := TRUE;
        IF Level <= LVL_LOW THEN
            State := 0;
        END_IF;

END_CASE;

FillValve := FillValve AND EStop;
Heater := Heater AND EStop AND (Level >= LIQ_MIN);
Agitator := Agitator AND EStop AND (Level >= LIQ_MIN);
DrainValve := DrainValve AND EStop;

END_PROGRAM

PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR
VAR_CONSTANT
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    LIQ_MIN : INT := 10;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
END_VAR
VAR
    State : INT := 0;
END_VAR

IF NOT EStop THEN
    State := 0;
END_IF;

CASE State OF
    0 : -- Idle
        IF StartBatch AND Level >= LIQ_MIN THEN
            State := 1;
        END_IF;

    1 : -- Fill
        FillValve := TRUE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
        IF Level >= LVL_HIGH THEN
            State := 2;
        END_IF;

    2 : -- Heat
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;
        IF Temp >= TEMP_SET THEN
            State := 3;
        END_IF;

    3 : -- React
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;
        IF TON_1.Q THEN
            State := 4;
        ELSE
            TON_1(IN := TRUE, PT := PT_REACT);
        END_IF;

    4 : -- Drain
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := TRUE;
        IF Level <= LVL_LOW THEN
            State := 0;
        END_IF;
END_CASE;

IF State = 1 OR State = 4 THEN
    FillValve := State = 1;
    DrainValve := State = 4;
ELSE
    FillValve := FALSE;
    DrainValve := FALSE;
END_IF;

IF NOT EStop OR (State = 1 OR State = 4) THEN
    Heater := FALSE;
    Agitator := FALSE;
END_IF;

END_PROGRAM

