        Fuel := FALSE;
        Ignition := FALSE;
        IF StartPB AND EStop THEN
            State := 1;
            PurgeTimer(IN := TRUE, PT := PT_PURGE);
        END_IF;

    1: // Pre-purge
        Fan := TRUE;
        Fuel := FALSE;
        Ignition := FALSE;
        IF PurgeTimer.Q THEN
            State := 2;
            IgniteTimer(IN := TRUE, PT := PT_IGN);
        END_IF;

    2: // Ignition trial
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := TRUE;
        IF NOT Flame OR IgniteTimer.Q THEN
            State := 0;
        END_IF;

    3: // Run
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := FALSE;
        IF NOT Flame OR StopPB OR NOT EStop THEN
            State := 0;
        END_IF;
END_CASE;

