    PT_IGN : TIME := T#2s;
END_VAR
VAR
    State : INT := 0;
    PurgeTimer : TON;
    IgniteTimer : TON;
END_VAR

CASE State OF
    0: // Off
        IF StartPB AND EStop THEN
            State := 1;
        END_IF;
        Fan := FALSE;
        Fuel := FALSE;
        Ignition := FALSE;

    1: // Pre-purge
        PurgeTimer(IN := TRUE, PT := PT_PURGE);
        IF PurgeTimer.Q THEN
            State := 2;
        END_IF;
        Fan := TRUE;
        Fuel := FALSE;
        Ignition := FALSE;

    2: // Ignition trial
        IgniteTimer(IN := TRUE, PT := PT_IGN);
        IF IgniteTimer.Q AND Flame THEN
