        IF NOT Flame OR StopPB OR NOT EStop THEN
            State := 0;
        END_IF;
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := FALSE;

END_CASE;

// Safety conditions
IF State = 2 THEN
    ASSERT Fan, 'Fuel valve must not be open without fan';
END_IF;

IF State = 2 OR State = 3 THEN
    ASSERT Ignition = Flame, 'Igniter must be off when flame is lost';
END_IF;

