PROGRAM conveyor3
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR
VAR CONSTANT
    PT_SEQ : TIME := T#2s;
END_VAR
VAR
    State : INT := 0;
END_VAR

IF NOT EStop THEN
    CASE State OF
        0:
            IF StartPB AND NOT StopPB THEN
                State := 1;
            END_IF;
        1:
            IF StartPB AND NOT StopPB THEN
                State := 2;
                C3 := TRUE;
                C2 := FALSE;
                C1 := FALSE;
            END_IF;
        2:
            IF StartPB AND NOT StopPB THEN
                State := 3;
                C3 := TRUE;
                C2 := TRUE;
                C1 := FALSE;
            END_IF;
        3:
            IF StartPB AND NOT StopPB THEN
                State := 3;
                C3 := TRUE;
                C2 := TRUE;
                C1 := TRUE;
            END_IF;
    END_CASE;
ELSIF StopPB OR NOT EStop THEN
    State := 0;
    C3 := FALSE;
    C2 := FALSE;
    C1 := FALSE;
END_IF;

END_PROGRAM

PROGRAM conveyor3
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR
VAR CONSTANT
    PT_SEQ : TIME := T#2s;
END_VAR
VAR
    State : INT := 0;
END_VAR

IF NOT EStop THEN
    CASE State OF
        0:
            IF StartPB AND NOT StopPB THEN
                State := 1;
            END_IF;
        1:
            IF StartPB AND NOT StopPB THEN
                IF T3.Q THEN
                    State := 2;
                END_IF;
            ELSE
                State := 0;
            END_IF;
        2:
            IF StartPB AND NOT StopPB THEN
                IF T4.Q THEN
                    State := 3;
                END_IF;
            ELSE
                State := 1;
            END_IF;
        3:
            IF NOT StartPB OR StopPB THEN
                State := 2;
            END_IF;
    END_CASE;

    CASE State OF
        0:
            C1 := FALSE;
            C2 := FALSE;
            C3 := FALSE;
        1:
            C1 := FALSE;
            C2 := FALSE;
            C3 := TRUE;
            T3(IN := TRUE, PT := PT_SEQ);
        2:
            C1 := FALSE;
            C2 := TRUE;
            C3 := TRUE;
            T4(IN := TRUE, PT := PT_SEQ);
        3:
            C1 := TRUE;
            C2 := TRUE;
            C3 := TRUE;
    END_CASE;

ELSE
    C1 := FALSE;
    C2 := FALSE;
    C3 := FALSE;
END_IF;
END_PROGRAM

PROGRAM conveyor3
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR
VAR
    State : INT;
    T_C2 : TON;
    T_C1 : TON;
END_VAR

IF NOT EStop OR StopPB THEN
    State := 0;
    C1 := FALSE;
    C2 := FALSE;
    C3 := FALSE;
ELSIF StartPB AND State = 0 THEN
    State := 1;
    C1 := FALSE;
    C2 := FALSE;
    C3 := TRUE;
ELSIF State = 1 AND T_C2.Q THEN
    State := 2;
    C1 := FALSE;
    C2 := TRUE;
    C3 := TRUE;
ELSIF State = 2 AND T_C1.Q THEN
    State := 3;
    C1 := TRUE;
    C2 := TRUE;
    C3 := TRUE;
END_IF;

CASE State OF
    1:
        T_C2(IN := TRUE, PT := T#2s);
        T_C1(IN := FALSE, PT := T#0s);
    2:
        T_C2(IN := TRUE, PT := T#2s);
        T_C1(IN := TRUE, PT := T#2s);
    3:
        T_C2(IN := TRUE, PT := T#2s);
        T_C1(IN := TRUE, PT := T#2s);
    ELSE:
        T_C2(IN := FALSE, PT := T#0s);
        T_C1(IN := FALSE, PT := T#0s);
END_CASE;
END_PROGRAM

PROGRAM conveyor3
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR
VAR
    State : INT := 0;
    T_C3 : TON;
    T_C2 : TON;
END_VAR

IF NOT EStop THEN
    CASE State OF
        0:
            IF StartPB AND NOT StopPB THEN
                State := 1;
                T_C3(IN := TRUE, PT := T#2s);
            END_IF;
        1:
            IF T_C3.Q THEN
                State := 2;
                T_C2(IN := TRUE, PT := T#2s);
            END_IF;
        2:
            IF T_C2.Q THEN
                State := 3;
            END_IF;
        3:
            IF StopPB OR NOT EStop THEN
                State := 0;
                T_C3(IN := FALSE);
                T_C2(IN := FALSE);
            END_IF;
    END_CASE;

    CASE State OF
        0: C1 := FALSE; C2 := FALSE; C3 := FALSE;
        1: C1 := FALSE; C2 := FALSE; C3 := TRUE;
        2: C1 := FALSE; C2 := TRUE; C3 := TRUE;
        3: C1 := TRUE; C2 := TRUE; C3 := TRUE;
    END_CASE;
END_IF;

END_PROGRAM

PROGRAM conveyor3
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR
VAR
    State : INT;
    T_C3 : TON;
    T_C2 : TON;
END_VAR

IF NOT EStop THEN
    CASE State OF
        0:
            IF StartPB AND StopPB THEN
                State := 0;
            ELSIF StartPB THEN
                State := 1;
            END_IF;
        1:
            IF StopPB OR EStop THEN
                State := 0;
            ELSIF T_C3.Q THEN
                State := 2;
            END_IF;
        2:
            IF StopPB OR EStop THEN
                State := 0;
            ELSIF T_C2.Q THEN
                State := 3;
            END_IF;
        3:
            IF StopPB OR EStop THEN
                State := 0;
            END_IF;
    END_CASE;

    T_C3(IN := TRUE, PT := T#2s);
    T_C2(IN := T_C3.Q, PT := T#2s);

    C3 := (State >= 1);
    C2 := (State >= 2);
    C1 := (State = 3);
ELSE
    State := 0;
    C1 := FALSE;
    C2 := FALSE;
    C3 := FALSE;
END_IF;
END_PROGRAM

